function present(ctx) { const s = getInstall(ctx); if (s) {ctx.saveInstallDraft(s);ctx.modal(renderInstall(ctx));} }
function alive(ctx, s) { return ctx.ui.install === s && !!document.querySelector(`[data-install-token="${s.token}"]`); }
function cancelTimers(s) { if (s) { (s.timers || []).forEach(clearTimeout); if (s.scanTimer) clearInterval(s.scanTimer); } }
function configErrors(c) {
  const [a, b, d] = c.tiers.map(Number);
  const out = [];
  if (!(a > 0 && a < b && b < d && d < 60)) out.push('Each tier must give a larger discount, between 1% and 59%.');
  if (!(Number.isInteger(+c.moq) && +c.moq >= 1 && +c.moq <= 1000)) out.push('Minimum order must be between 1 and 1,000 pieces.');
  if (!(+c.weeklyMessages >= 0 && +c.weeklyMessages <= 20 && Number.isInteger(+c.weeklyMessages))) out.push('Weekly message limit must be a whole number between 0 and 20.');
  if (!(+c.followups >= 0 && +c.followups <= 10 && Number.isInteger(+c.followups))) out.push('Follow-up limit must be a whole number between 0 and 10.');
  return out;
}
function canNext(s) { return s.step === 0 ? s.shop === 'done' && connected({connectors:s.connections},'whatsapp') && connected({connectors:s.connections},'shiprocket') && (!s.gstRequired || s.gst === 'done') : s.step === 1 ? !configErrors(s.draft).length : s.step === 2 ? s.scan === 100 : s.step === 3 ? s.authorised : s.phase === 'done'; }
function timeLabel(value) { const h = Number(String(value).split(':')[0]); return `${h % 12 || 12} ${h < 12 ? 'am' : 'pm'}`; }
function draftPreview(s) {
  const c = s.draft;
  const unit = base => Math.round(base * (1 - (Number(c.tiers[1]) || 0) / 100));
  const sub = 40 * unit(427) + 40 * unit(142), tax = Math.round(sub * .05), total = sub + tax;
  const needsApproval = c.mode !== 'auto' || c.quoteLimit === 0 || total > c.quoteLimit;
  return `<div class="stack ob-live"><div class="ob-eyebrow">LIVE PREVIEW</div><div class="ob-whatsapp"><div class="row ob-whatsapp-head"><span class="ob-avatar">KL</span><div><strong>Kesar Linen Co.</strong><span>WhatsApp intro</span></div>${icon('message', 20)}</div><div class="ob-message-area"><span class="ob-message-meta">After delivery · quiet ${timeLabel(c.quietStart)}–${timeLabel(c.quietEnd)} · max ${esc(String(c.weeklyMessages))} a week</span><div class="ob-message">Hi, thanks for your order from Kesar Linen Co. If you’re buying for a PG, hotel, salon or office, we can send a GST invoice in your firm’s name and trade prices on ${esc(String(c.moq || 10))}+ pieces. Reply <strong>YES</strong> for trade prices, <strong>CALL</strong> for a call back, or <strong>STOP</strong> to opt out.<span class="ob-message-time">10:00 ✓✓</span></div></div></div><div class="card ob-sample"><div class="ob-eyebrow">SAMPLE QUOTE</div><p>40 single bedsheets + 40 pillow covers</p><div class="row"><span class="muted">Tier 2 · ${esc(String(c.tiers[1]))}% off</span><span>${money(sub)}</span></div><div class="row"><span class="muted">IGST 5%</span><span>${money(tax)}</span></div><div class="row ob-total"><strong>Total</strong><strong>${money(total)}</strong></div>${badge(needsApproval ? c.quoteLimit === 0 ? 'Every quote comes to you' : c.mode==='review'?'Review-first · approval required':`Above ${money(c.quoteLimit)} · comes to you` : 'Within your rules', needsApproval ? 'amber' : 'green')}</div></div>`;
}
function input(name, label, value, extra = '') { return `<label class="field ob-field"><span>${label}</span><input type="number" data-action="ob-config" data-key="${name}" ${attrs(value)} ${extra}></label>`; }
function radio(name, current, value, label, recommended = false) { return `<label class="ob-radio ${String(current) === String(value) ? 'selected' : ''}"><input type="radio" name="${name}" data-action="ob-config" data-key="${name}" value="${esc(String(value))}" ${String(current) === String(value) ? 'checked' : ''}><span>${label}</span>${recommended ? badge('Recommended', 'green') : ''}</label>`; }
function toggle(name, checked, label, description = '') { return `<label class="ob-toggle-row"><div><strong>${label}</strong>${description ? `<span class="muted">${description}</span>` : ''}</div><input class="ob-switch" type="checkbox" data-action="ob-config" data-key="${name}" ${checked ? 'checked' : ''} aria-label="${label}"></label>`; }
function connectionState(s,id){
  if(s.connecting?.includes(id))return 'loading';
  return id==='shop'?s.shop:id==='gst'?s.gst:connected({connectors:s.connections},{pay:'payments',ship:'shiprocket',wa:'whatsapp',voice:s.voice==='sv'?'sarvam':'elevenlabs'}[id])?'done':'idle';
}
function connectionStatus(s,id){
  const status=connectionState(s,id);
  return `${status==='idle'?button('Connect demo','ob-connect','primary',`data-key="${id}"`):status==='loading'?'<span class="row muted ob-status-change"><span class="ob-spinner" aria-hidden="true"></span>Connecting demo…</span>':`<span class="row ob-connected ob-status-change"><span class="ob-status-dot"></span>${id==='shop'?'Connected · kesarlinen.myshopify.com':id==='gst'?`Connected · ${esc(s.gstChoice)}`:'Demo enabled'}</span>`}<span class="ob-required">${id==='voice'||(id==='gst'&&!s.gstRequired)?'OPTIONAL':'REQUIRED'}</span>`;
}
function connectionCard(s,id,name,i,tint,desc,options=''){
  const displayName=id==='gst'?s.gstChoice:name;
  return `<div class="card ob-connect-card" data-connection-key="${id}"><div class="ob-connect-brand ${tint}">${icon(i,28)}<span>${esc(displayName)}</span></div><div class="ob-connect-copy"><h3>${name}</h3><p class="muted">${desc}</p>${options}<div class="row ob-connect-status" role="status" aria-live="polite" aria-atomic="true" tabindex="-1">${connectionStatus(s,id)}</div></div></div>`;
}
function refreshConnection(ctx,s,id){
  s.connections=ctx.state.connectors;
  const card=document.querySelector(`[data-connection-key="${id}"]`),status=card?.querySelector('.ob-connect-status');
  if(!status)return;
  const hadFocus=card.contains(document.activeElement);
  status.innerHTML=connectionStatus(s,id);
  if(id==='gst'&&s.gst!=='idle')card.querySelector('.ob-segment')?.remove();
  refreshDynamic(ctx);
  if(hadFocus)status.focus({preventScroll:true});
}
