function configStep(s) {
  const c = s.draft;
  const facts = [['globe', 'Website', 'kesarlinen.in'], ['store', 'Store platform', 'Shopify · demo connected'], ['package', 'Business type', 'D2C home textiles'], ['package', 'Catalogue size', '~640 products'], ['lightning', 'Average order value', '₹1,300']];
  return `<div class="ob-config-layout"><div class="stack ob-config-main">${title('Recommended setup', 'Start with safe defaults. You can adjust every rule later.')}<div class="card stack ob-recommended"><strong>Review-first · you approve every outgoing action</strong><p>Trade discounts ${c.tiers.join('%, ')}% · minimum ${esc(c.moq)} pieces</p><p>${esc(c.confidence)}% confidence · ${esc(c.weeklyMessages)} messages a week · quiet ${timeLabel(c.quietStart)}–${timeLabel(c.quietEnd)}</p>${button('Use recommended defaults','ob-defaults','secondary')}</div><details class="ob-advanced" ${configErrors(c).length?'open':''}><summary>Customize pricing and outreach ${icon('chevron-down',16)}</summary><div class="stack"><section class="stack"><h3>Kesar Linen · Shopify · home textiles</h3><span class="muted ob-small">A starting point from your demo store.</span><div class="ob-business-facts">${facts.slice(0,3).map(([i, label, value]) => `<div class="row">${icon(i, 20)}<div><strong>${label}</strong><span class="muted">${value}</span></div></div>`).join('')}</div><div class="ob-facts-extra"><span><strong>Top categories</strong> Bedsheets 54% · towels 27% · covers 19%</span><span><strong>Market</strong> Pan India · ships from Panipat, Haryana</span><span><strong>GSTIN</strong> 06AA•••••1Z4 · Haryana</span></div></section><section class="stack"><h3>2. Trade pricing</h3><p class="muted ob-small">A suggested starting point based on your margins.</p><div class="ob-tier-table"><div class="ob-tier-head"><span>Quantity</span><span>Discount</span><span>Single bedsheet</span></div>${['10–24 pieces', '25–49 pieces', '50+ pieces'].map((label, i) => `<div class="ob-tier-row"><span>${label} ${i === 2 ? badge('Floor', 'gray') : ''}</span><label><input aria-label="Tier ${i + 1} discount" type="number" min="1" max="59" data-action="ob-config" data-key="tier${i}" ${attrs(c.tiers[i])}><span class="muted">% off</span></label><strong id="ob-tier-price-${i}">${money(Math.round(427 * (1 - c.tiers[i] / 100)))}</strong></div>`).join('')}</div><div id="ob-config-error" class="ob-error" role="status">${configErrors(c).map(esc).join('<br>')}</div><div class="row ob-wrap"><span class="muted ob-small">Tiers apply to anyone who meets the quantity.</span>${input('moq', 'Minimum order (pieces)', c.moq, 'min="1" max="1000"')}</div></section><section class="stack"><h3>3. Approvals</h3><strong>Quote limit for future automatic mode</strong><div class="stack ob-radio-list">${[[10000, '₹10,000 and below'], [15000, '₹15,000 and below'], [25000, '₹25,000 and below'], [0, 'Ask me for every quote']].map(([v, label]) => radio('quoteLimit', c.quoteLimit, v, label, v === 15000)).join('')}</div><p class="muted ob-small">Review-first asks you for every outgoing action. This limit applies when you unlock automatic mode after 14 days.</p><strong>Below-floor requests</strong><div class="stack ob-radio-list">${radio('floorHandling', c.floorHandling || 'queue', 'queue', 'Queue for my approval')}${radio('floorHandling', c.floorHandling || 'queue', 'decline', 'Decline politely and offer my tiers')}</div></section><section class="stack"><h3>4. Outreach</h3><label class="field ob-range"><span>Contact buyers with confidence of <strong id="ob-confidence-label">${(+c.confidence / 100).toFixed(2)} or more</strong></span><input type="range" min="50" max="95" step="1" data-action="ob-config" data-key="confidence" ${attrs(c.confidence)}><span class="row muted ob-small"><span>0.50 · more buyers, more misses</span><span>0.95 · fewer, surer</span></span></label><div class="grid-2">${input('weeklyMessages', 'Messages per buyer per week, at most', c.weeklyMessages, 'min="0" max="20"')}${input('followups', 'Follow-ups in total, at most', c.followups, 'min="0" max="10"')}</div><div class="row ob-wrap ob-quiet">${icon('clock', 16)}<span>Quiet hours from</span><select aria-label="Quiet hours start" data-action="ob-config" data-key="quietStart">${['20:00', '21:00', '22:00'].map(v => `<option value="${v}" ${c.quietStart === v ? 'selected' : ''}>${timeLabel(v)}</option>`).join('')}</select><span>to</span><select aria-label="Quiet hours end" data-action="ob-config" data-key="quietEnd">${['08:00', '09:00', '10:00'].map(v => `<option value="${v}" ${c.quietEnd === v ? 'selected' : ''}>${timeLabel(v)}</option>`).join('')}</select></div>${toggle('credit', c.credit, 'Credit terms', 'Requests for credit always come to you for approval.')}</section></div></details><div id="ob-config-summary-error" class="ob-error" role="status">${configErrors(c).map(esc).join('<br>')}</div></div><aside id="ob-live-preview">${draftPreview(s)}</aside></div>`;
}
const TYPES = [['PGs and hostels', 514], ['Hotels and homestays', 230], ['Salons and spas', 189], ['Offices and gifting', 162], ['Cafés and restaurants', 122], ['Schools', 68], ['Other', 67]];
const DETECTIONS = [['Urban Nest Co-living', 'Pune', '.96', 'One UPI ID → 3 addresses', '36 bedsheets in 3 orders'], ['Glow Unisex Salon', 'Bengaluru', '.94', 'Towels about every 30 days', '“Salon” in name'], ['Royal Palms Banquets', 'Ludhiana', '.91', '80 hand towels in one order', '“Banquets” in name'], ['Backpackers’ Nest Hostel', 'Rishikesh', '.89', '“Hostel” in name', '24 single bedsheets'], ['Shanti Guest House', 'Varanasi', '.88', '“Guest House” in name', '30 bath towels']];
const SCAN_PHASES = ['Grouping orders by payer…', 'Reading shipping names and addresses…', 'Comparing with the 212 buyers who typed a GSTIN…', 'Scoring repeat rhythm and order size…', 'Checking WhatsApp opt-ins…'];
function scanStep(s) {
  return `${title('Scan your orders', 'A one-time look back to find the business buyers already in your checkout.')}${s.scan < 100 ? `<div class="card ob-scan-progress"><div class="row"><span class="ob-spinner"></span><strong>Reading 1,15,240 demo orders</strong><span id="ob-scan-percent">${s.scan}%</span></div><p class="muted ob-small">1 Mar – 28 Aug 2026 · synthetic order history</p><div class="ob-progress"><span id="ob-scan-bar" style="width:${s.scan}%"></span></div><span id="ob-scan-phase" class="muted">${SCAN_PHASES[0]}</span></div><div class="grid-3 ob-skeletons"><div></div><div></div><div></div></div><div class="ob-skeleton-large"></div>` : `<div class="ob-scan-result"><div><span class="ob-link ob-small">${icon('check', 15)} SCAN COMPLETE</span><h2>1,352 business buyers</h2><span>1.40% of your customers</span></div><div><strong>₹27.1 L</strong><span class="muted">of sales in 6 months (1.81%)</span></div></div><div class="grid-3 ob-scan-stats">${[[212, 'Typed a GSTIN', 'Handled by the rule'], [1140, 'Found by the agent', 'Didn’t identify themselves'], [486, 'Possible', 'Need more evidence · not counted']].map(([n, h, p]) => `<div class="card"><strong>${n.toLocaleString('en-IN')}</strong><h3>${h}</h3><p class="muted ob-small">${p}</p></div>`).join('')}</div><div class="grid-2"><div class="card ob-types"><h3>By type</h3>${TYPES.map(([n, v]) => `<div><span>${n}</span><div class="ob-type-track"><span style="width:${v / 514 * 100}%"></span></div><strong>${v}</strong></div>`).join('')}</div><div class="card ob-detections"><h3>Top detections</h3>${DETECTIONS.map(([n, city, score, e1, e2]) => `<div><div class="row"><strong>${esc(n)}</strong><span class="muted ob-small">${city}</span><span class="ob-positive">0${score}</span></div><div class="row ob-wrap">${badge(e1, 'gray')}${badge(e2, 'gray')}</div></div>`).join('')}</div></div><div class="callout ob-illustrative">${badge('ILLUSTRATIVE', 'gray')}<span>About <strong>₹66 L extra revenue</strong> and <strong>₹29 L extra gross margin</strong> a year at your size. This demo estimate is a base case; the dashboard tracks synthetic results.</span></div>`}`;
}
function permissionStep(s) {
  const c = s.draft;
  const summary = [['AGENT', AGENTS[s.agent]?.name || 'B2B Customer Agent'], ['OPERATING MODE', 'Review-first · every outgoing action needs approval'], ['NOTIFICATIONS', c.approvalWhatsapp ? 'WhatsApp, Dashboard' : 'Dashboard'], ['DATA ACCESS', 'Read · act within your rules'], ['TRADE TIERS', `${c.tiers.join('% · ')}% floor`], ['BUYERS FOUND', '1,140 found by the agent']];
  const caps = ['Read checkout orders, payments and payer IDs', 'Read orders, catalogue and stock from Shopify', 'Read delivery status from Shiprocket', 'Message opted-in buyers on WhatsApp, within your limits', 'Create quotes, GST invoices and payment links', 'Call buyers only when they ask for a call'];
  return `${title('Review permissions', 'Review your configuration and confirm the demo installation.')}<div class="grid-2 ob-permission-summary">${summary.map(([h, v]) => `<div><span class="ob-eyebrow">${h}</span><strong ${h === 'NOTIFICATIONS' ? 'id="ob-permission-notifications"' : ''}>${esc(v)}</strong></div>`).join('')}</div><div class="card ob-capabilities"><h3>${icon('shield', 18)} Capabilities and permissions</h3>${caps.map(p => `<p>${icon('check', 17)} ${p}</p>`).join('')}<p>${icon('lock', 17)} Review-first: every outgoing message, quote, invoice, payment link and call needs your approval</p></div><div class="stack ob-radio-list"><strong>Mode</strong><div class="ob-radio selected"><span class="ob-radio-mark"></span><div><strong>Review-first ${badge('Recommended', 'green')}</strong><p class="muted ob-small">The agent drafts everything; you approve before anything is sent.</p></div></div><div class="ob-radio ob-disabled"><span class="ob-radio-mark"></span><div><strong>Auto within your rules</strong><p class="muted ob-small">Available after 14 days of review-first.</p></div>${icon('lock', 17)}</div></div>${toggle('approvalWhatsapp', c.approvalWhatsapp, 'Send approvals to my WhatsApp', '+91 99XXX XX107 · approve or reject with one tap')}<p class="ob-small muted"><strong>2% of business orders it closes.</strong> Free for 30 days (up to ₹5,000 credit). WhatsApp and calls at actuals, about ₹2,200 a month.</p><label class="ob-authorise"><input type="checkbox" data-action="ob-authorise" ${s.authorised ? 'checked' : ''}><span>I authorise <strong>${esc(AGENTS[s.agent]?.name || 'B2B Customer Agent')}</strong> to use the simulated accounts and perform demo actions according to these configuration settings.</span></label><div class="ob-demo-note">${icon('info', 15)} This installation uses synthetic data. No messages or payments are sent.</div>`;
}
function activationStep(s) {
  return s.phase === 'activating' ? `<div class="ob-activated"><div class="icon-tile ob-icon-large blue"><span class="ob-spinner ob-spinner-large"></span></div><h2>Activating your demo agent…</h2><p class="muted">Saving your configuration and preparing the dashboard.</p></div>` : `<div class="ob-activated">${iconTile('check', 'green', true)}<h2>Agent activated successfully</h2><p class="muted">${esc(AGENTS[s.agent]?.name || 'B2B Customer Agent')} is ready in review-first mode. Monitor its activity and approve proposed actions from your dashboard.</p><div class="card ob-next-steps"><strong>Next steps</strong><p>${icon('clock', 18)} Approve the first intro batch</p><p>${icon('message', 18)} Review your approval requests</p><p>${icon('chart', 18)} Explore activity and business buyers</p></div><span class="ob-demo-note">${icon('info', 15)} The dashboard opens a synthetic business snapshot.</span></div>`;
}
function renderInstall(ctx) {
  const s = getInstall(ctx);s.connections=ctx.state.connectors;
  const hint = s.step === 0 && !canNext(s) ? 'Connect the required tools to continue' : s.step === 1 && !canNext(s) ? 'Review the highlighted configuration fields' : s.step === 2 && s.scan < 100 ? 'Scanning demo orders…' : s.step === 3 && !s.authorised ? 'Tick the authorisation to install' : '';
  return `<div class="ob-wizard" role="dialog" aria-modal="true" aria-labelledby="ob-wizard-title" data-install-token="${s.token}"><header class="ob-wizard-head"><h2 id="ob-wizard-title">Install ${esc(AGENTS[s.agent]?.name || 'B2B Customer Agent')}</h2>${badge('Setup wizard', 'blue')}${button(icon('x', 19), 'ob-cancel', 'ghost', 'aria-label="Close installation"')}</header><div class="ob-wizard-body"><aside class="ob-stepper">${STEPS.map((t, i) => `<button class="ob-step ${i === s.step ? 'current' : ''} ${i < s.step || (i === 4 && s.phase === 'done') ? 'done' : ''}" data-action="ob-step" data-step="${i}" ${i >= s.step || s.step === 4 ? 'disabled' : ''}><span>${i < s.step || (i === 4 && s.phase === 'done') ? icon('check', 16) : i + 1}</span><strong>${t}</strong></button>`).join('')}<div class="ob-step-help">${icon('book', 27)}<div><strong>Need help?</strong>${button('How this agent works', 'ob-help', 'ghost')}</div></div></aside><div class="ob-workspace"><div class="ob-wizard-content" id="ob-wizard-content">${[connectStep, configStep, scanStep, permissionStep, activationStep][s.step](s)}</div><footer class="ob-wizard-foot">${s.step > 0 && s.step < 4 ? button('Previous', 'ob-previous') : ''}<span class="muted ob-small" id="ob-foot-hint">${hint}</span>${s.phase !== 'activating' ? button(s.step === 4 ? 'Go to dashboard' : s.step === 3 ? 'Install agent' : `Next ${icon('chevron-right', 15)}`, 'ob-next', 'primary', `id="ob-next" ${canNext(s) ? '' : 'disabled'}`) : ''}</footer></div></div></div>`;
}

export function openInstall(ctx, agent = 'business') {
  if (agent !== 'business') { presentPreview(ctx, agent); return; }
  cancelTimers(getInstall(ctx));
  ctx.ui.install = { token: String(Date.now()) + Math.random().toString(36).slice(2, 7), agent, step: 0, shop: connected(ctx.state,'shopify')?'done':'idle', gst: connected(ctx.state,ctx.state.installDraft?.gstChoice==='Zoho Books'?'zoho':'tally')?'done':'idle', gstRequired:false, gstChoice: 'Tally', wa: 'builtin', waVendor: 'Interakt', voice: 'el', draft: { ...DEFAULT_CONFIG, ...ctx.state.config, tiers: [...(ctx.state.config?.tiers || DEFAULT_CONFIG.tiers)] }, scan: 0, authorised: false, phase: null, ...ctx.state.installDraft, draft:{...DEFAULT_CONFIG,...ctx.state.config,...ctx.state.installDraft?.draft,mode:'review',tiers:[...(ctx.state.installDraft?.draft?.tiers||ctx.state.config.tiers||DEFAULT_CONFIG.tiers)]},connecting:[],timers: [] };
  if(ctx.ui.install.step===2&&ctx.ui.install.scan<100)beginScan(ctx,ctx.ui.install);
  present(ctx);
}
function refreshDynamic(ctx) {
  const s = getInstall(ctx); if (!s) return;ctx.saveInstallDraft(s);
  s.connections=ctx.state.connectors;const next = document.getElementById('ob-next'); if (next) next.disabled = !canNext(s);
  if (s.step === 1) {
    const preview = document.getElementById('ob-live-preview'); if (preview) preview.innerHTML = draftPreview(s);
    const summaryError=document.getElementById('ob-config-summary-error');if(summaryError)summaryError.innerHTML=configErrors(s.draft).map(esc).join('<br>');
    const error = document.getElementById('ob-config-error'); if (error) error.innerHTML = configErrors(s.draft).map(esc).join('<br>');
    s.draft.tiers.forEach((v, i) => { const p = document.getElementById(`ob-tier-price-${i}`); if (p) p.textContent = money(Math.round(427 * (1 - Number(v) / 100))); });
    const confidence = document.getElementById('ob-confidence-label'); if (confidence) confidence.textContent = `${(s.draft.confidence / 100).toFixed(2)} or more`;
    document.querySelectorAll('.ob-radio input').forEach(el => el.closest('.ob-radio')?.classList.toggle('selected', el.checked));
  }
  if (s.step === 3) { const notifications = document.getElementById('ob-permission-notifications'); if (notifications) notifications.textContent = s.draft.approvalWhatsapp ? 'WhatsApp, Dashboard' : 'Dashboard'; }
  const hint = document.getElementById('ob-foot-hint'); if (hint) hint.textContent = !canNext(s) ? s.step === 1 ? 'Review the highlighted configuration fields' : s.step === 3 ? 'Tick the authorisation to install' : s.step===0?'Connect the required tools to continue':'' : '';
}
function beginScan(ctx, s) {
  if (s.scan === 100 || s.scanTimer) return;
  const start = performance.now();
  s.scanTimer = setInterval(() => {
    if (!alive(ctx, s)) { clearInterval(s.scanTimer); s.scanTimer = null; return; }
    s.scan = Math.min(100, Math.round((performance.now() - start) / 2200 * 100));
    const pct = document.getElementById('ob-scan-percent'), bar = document.getElementById('ob-scan-bar'), phase = document.getElementById('ob-scan-phase');
    if (pct) pct.textContent = `${s.scan}%`; if (bar) bar.style.width = `${s.scan}%`; if (phase) phase.textContent = SCAN_PHASES[Math.min(4, Math.floor(s.scan / 20))];
    if (s.scan === 100) { clearInterval(s.scanTimer); s.scanTimer = null; if (s.step === 2) present(ctx); }
  }, 80);
}

export function handleOnboarding(action, el, ctx) {
  if (!action?.startsWith('ob-')) return false;
  if (action === 'ob-back') { ctx.nav('studio'); return true; }
  if (action === 'ob-dashboard') { ctx.nav('dashboard'); return true; }
  if (action === 'ob-open-install') { openInstall(ctx, el?.dataset?.agent || 'business'); return true; }
  if (action === 'ob-preview') { presentPreview(ctx, el?.dataset?.agent || 'cart'); return true; }
  if (action === 'ob-close-preview') { ctx.closeOverlay(); return true; }
  if (action === 'ob-run-preview') { const id = el?.dataset?.agent || 'cart'; ctx.ui.agentPreviewResult = id; presentPreview(ctx, id); ctx.toast(`${AGENTS[id]?.name || 'Agent'} demo complete · ready for review`); return true; }
  const s = getInstall(ctx); if (!s) return true;
  if (action === 'ob-cancel') { ctx.saveInstallDraft(s);cancelTimers(s);ctx.closeOverlay();ctx.rerender(); return true; }
  if(action==='ob-defaults'){s.draft={...s.draft,...DEFAULT_CONFIG,tiers:[...DEFAULT_CONFIG.tiers]};present(ctx);return true;}
  if(action==='ob-turnover'){s.gstRequired=el.value==='yes';present(ctx);return true;}
  if (action === 'ob-help') { ctx.toast('Connect demo tools, set your rules, then review every action from the dashboard.'); return true; }
  if (action === 'ob-connect') {
    const k = el.dataset.key; if (!['shop','gst','wa','ship','voice'].includes(k) ||s.connecting?.includes(k)|| (['shop','gst'].includes(k)&&s[k]!=='idle')) return true;
    s.connecting=[...(s.connecting||[]),k];if(['shop','gst'].includes(k))s[k]='loading';refreshConnection(ctx,s,k);
    s.timers.push(setTimeout(() => { if (!alive(ctx, s)) return; s.connecting=(s.connecting||[]).filter(id=>id!==k);if(['shop','gst'].includes(k))s[k]='done';ctx.connect(k==='shop'?'shopify':k==='gst'?(s.gstChoice==='Tally'?'tally':'zoho'):{wa:'whatsapp',ship:'shiprocket',voice:s.voice==='sv'?'sarvam':'elevenlabs'}[k]);refreshConnection(ctx,s,k);ctx.toast(`${{shop:'Shopify',gst:s.gstChoice,wa:'WhatsApp',ship:'Shiprocket',voice:s.voice==='sv'?'Sarvam AI':'ElevenLabs'}[k]} demo connected`); }, 650)); return true;
  }
  if (action === 'ob-gst-choice') { if (s.gst === 'idle') { s.gstChoice = el.dataset.choice; present(ctx); } return true; }
  if (action === 'ob-tool-choice') { s[el.dataset.key] = el.value; present(ctx); return true; }
  if (action === 'ob-config') {
    const k = el.dataset.key;
    if (k.startsWith('tier')) s.draft.tiers[Number(k.slice(4))] = el.value === '' ? '' : Number(el.value);
    else if (el.type === 'checkbox') s.draft[k] = el.checked;
    else if (['moq', 'quoteLimit', 'confidence', 'weeklyMessages', 'followups'].includes(k)) s.draft[k] = el.value === '' ? '' : Number(el.value);
    else s.draft[k] = el.value;
    refreshDynamic(ctx); return true;
  }
  if (action === 'ob-authorise') { s.authorised = el.checked; refreshDynamic(ctx); return true; }
  if (action === 'ob-previous' || action === 'ob-step') {
    const target = action === 'ob-previous' ? s.step - 1 : Number(el.dataset.step);
    if (s.step === 4 || target < 0 || target >= s.step) return true;
    s.step = target; present(ctx); return true;
  }
  if (action === 'ob-next') {
    if (!canNext(s)) return true;
    if (s.step === 4) {cancelTimers(s);ctx.ui.install=null;ctx.closeOverlay(false);ctx.nav('dashboard');return true;}
    s.step += 1;
    if (s.step === 4) s.phase = 'activating';
    present(ctx);
    if (s.step === 2) beginScan(ctx, s);
    if (s.step === 4) s.timers.push(setTimeout(() => { if (!alive(ctx, s)) return; ctx.saveConfig({...s.draft,mode:'review',tiers:s.draft.tiers.map(Number),gstProvider:s.gstChoice,whatsappProvider:s.wa==='own'?s.waVendor:'Built-in',voiceProvider:s.voice==='el'?'ElevenLabs':'Sarvam AI'});ctx.activate(false);s.phase='done';present(ctx);},900));
    return true;
  }
  return true;
}
